namespace sv_d2fdf669ab0444afbb6b3b3789197f4f.Client.Models;

public sealed class Shipment
{
    public required string TrackingNumber { get; init; }
    public required string Status { get; init; }
    public required string Location { get; init; }
    public DateTimeOffset? EstimatedDelivery { get; init; }
    public required IReadOnlyList<StatusUpdate> StatusUpdates { get; init; }
}

public sealed class StatusUpdate
{
    public required string Description { get; init; }
    public required DateTimeOffset Timestamp { get; init; }
    public string? Location { get; init; }
}

using sv_d2fdf669ab0444afbb6b3b3789197f4f.Client.Models;

namespace sv_d2fdf669ab0444afbb6b3b3789197f4f.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_d2fdf669ab0444afbb6b3b3789197f4f.Client.Models;
using sv_d2fdf669ab0444afbb6b3b3789197f4f.Client.Services;

namespace sv_d2fdf669ab0444afbb6b3b3789197f4f.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> Seeds = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment
        {
            TrackingNumber = "PKG-001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 21, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Timestamp = new DateTimeOffset(2026, 6, 15, 9, 0, 0, TimeSpan.Zero), Location = "New York, NY" },
                new StatusUpdate { Description = "Departed facility", Timestamp = new DateTimeOffset(2026, 6, 16, 6, 30, 0, TimeSpan.Zero), Location = "New York, NY" },
                new StatusUpdate { Description = "Arrived at hub", Timestamp = new DateTimeOffset(2026, 6, 17, 14, 0, 0, TimeSpan.Zero), Location = "Chicago, IL" },
            ]
        },
        ["PKG-002"] = new Shipment
        {
            TrackingNumber = "PKG-002",
            Status = "Delivered",
            Location = "San Francisco, CA",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 16, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Package picked up", Timestamp = new DateTimeOffset(2026, 6, 12, 10, 0, 0, TimeSpan.Zero), Location = "Seattle, WA" },
                new StatusUpdate { Description = "In transit", Timestamp = new DateTimeOffset(2026, 6, 13, 8, 0, 0, TimeSpan.Zero), Location = "Portland, OR" },
                new StatusUpdate { Description = "Out for delivery", Timestamp = new DateTimeOffset(2026, 6, 16, 7, 0, 0, TimeSpan.Zero), Location = "San Francisco, CA" },
                new StatusUpdate { Description = "Delivered", Timestamp = new DateTimeOffset(2026, 6, 16, 11, 45, 0, TimeSpan.Zero), Location = "San Francisco, CA" },
            ]
        },
        ["PKG-003"] = new Shipment
        {
            TrackingNumber = "PKG-003",
            Status = "Processing",
            Location = "Dallas, TX",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 25, 18, 0, 0, TimeSpan.Zero),
            StatusUpdates =
            [
                new StatusUpdate { Description = "Label created", Timestamp = new DateTimeOffset(2026, 6, 17, 15, 0, 0, TimeSpan.Zero), Location = "Dallas, TX" },
            ]
        },
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        Seeds.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_d2fdf669ab0444afbb6b3b3789197f4f.Client.Models
@using sv_d2fdf669ab0444afbb6b3b3789197f4f.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracking> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p>Loading shipment details for <strong>@TrackingNumber</strong>…</p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger">
        <p>@_errorMessage</p>
        <button class="btn btn-primary" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="alert alert-warning">
        <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
    </div>
}
else
{
    <h3>Shipment @_shipment.TrackingNumber</h3>
    <dl>
        <dt>Status</dt>
        <dd>@_shipment.Status</dd>
        <dt>Location</dt>
        <dd>@_shipment.Location</dd>
        <dt>Estimated Delivery</dt>
        <dd>@(_shipment.EstimatedDelivery?.ToString("f") ?? "N/A")</dd>
    </dl>

    <h4>Tracking History</h4>
    @if (_shipment.StatusUpdates.Count == 0)
    {
        <p>No status updates available.</p>
    }
    else
    {
        <table class="table">
            <thead>
                <tr>
                    <th>Time</th>
                    <th>Description</th>
                    <th>Location</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in _shipment.StatusUpdates)
                {
                    <tr>
                        <td>@update.Timestamp.ToString("g")</td>
                        <td>@update.Description</td>
                        <td>@(update.Location ?? "—")</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    private static readonly TimeSpan RequestTimeout = TimeSpan.FromSeconds(30);

    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;
    private string? _loadedTrackingNumber;

    protected override Task OnParametersSetAsync()
    {
        if (string.Equals(_loadedTrackingNumber, TrackingNumber, StringComparison.OrdinalIgnoreCase))
            return Task.CompletedTask;

        return LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        CancelPending();

        _loadedTrackingNumber = TrackingNumber;
        _shipment = null;
        _errorMessage = null;
        _loading = true;

        var cts = CancellationTokenSource.CreateLinkedTokenSource(CancellationToken.None);
        cts.CancelAfter(RequestTimeout);
        _cts = cts;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, cts.Token);
        }
        catch (OperationCanceledException) when (cts.IsCancellationRequested && !_disposed)
        {
            // If the page is being disposed or navigated away, don't update state.
            if (_disposed || !string.Equals(_loadedTrackingNumber, TrackingNumber, StringComparison.OrdinalIgnoreCase))
                return;

            _errorMessage = "The request timed out. Please try again.";
            Logger.LogWarning("Shipment request for {TrackingNumber} timed out.", TrackingNumber);
        }
        catch (OperationCanceledException)
        {
            // Cancelled due to navigation or disposal — nothing to do.
            return;
        }
        catch (Exception ex)
        {
            if (_disposed)
                return;

            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
            Logger.LogError(ex, "Failed to load shipment {TrackingNumber}.", TrackingNumber);
        }
        finally
        {
            _loading = false;
        }
    }

    private Task RetryAsync() => LoadShipmentAsync();

    private void CancelPending()
    {
        var cts = _cts;
        if (cts is not null)
        {
            cts.Cancel();
            cts.Dispose();
            _cts = null;
        }
    }

    private bool _disposed;

    public void Dispose()
    {
        _disposed = true;
        CancelPending();
    }
}

